```xml
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <script src="Scripts/jquery-2.1.1.min.js"></script>
    <title>Страница 2</title>
    <style>
        #play {
            width:520px;
            height:520px;
        }
        .brick {
            width:120px;
            height:120px;
            background-color:aqua;
            margin:3px;
            border:solid 1px silver;
            display: inline-block;
            font-size:33px;
            text-align:center;
        }
        #start {
            width: 150px;
            height: 100px;
            font-size: 32px;
        }
    </style>
</head>
<body>
    <h2>Игра</h2>
    <div id="counter"></div>
    <div id="play"></div>
    <button id="start" >Старт</button>
    <script>
        var arr = new Array(); // массив для хранения значений
        var seconds = 0; // время игры
        var timerId; // объект таймера
        $(function () {

            createGame();

            $("#start").click(function () {
                timerId = setInterval(timerFunction, 1000);
            })
            // обработчик нажатия отдельной клетки
            $(".brick").click(function () {
                var intVal = parseInt($(this).text(), 10);
                if (arr[arr.length - 1] === intVal) {

                    arr.pop();
                    $(this).css("background-color", "brown");
                }
            })
        });
        // функция таймера
        function timerFunction() {
            seconds++;
            $("#counter").text(seconds);
            if (arr.length == 0){
                clearInterval(timerId);
                $("#counter").text("Вы нашли все числа за " + seconds + " секунд");
            }  
        };
        // создание игры
        function createGame() {
            for (var i = 0; i < 4; i++) {
                for (var j = 0; j < 4; j++) {
                    var newBrick = $("<div class='brick'></div>");
                    var randomInt = getRandomInt(1, 100);
                    arr.push(randomInt);
                    newBrick.text(randomInt);
                    $("#play").append(newBrick);
                }
            }
            arr.sort(sortFunction);
        };
        // получение случайного числа
        function getRandomInt(min, max) {
            return Math.floor(Math.random() * (max - min + 1)) + min;
        };
        // функция обратной сортировки
        function sortFunction(a, b){
            if (a > b)
                return -1;
            if (a < b)
                return 1;
            return 0;
        }
    </script>
</body>
</html>
```

