```c#
private void addButton_Click(object sender, RoutedEventArgs e)
{
    long year = -1;
    if(Int64.TryParse(yearBox.Text,out year) && !String.IsNullOrWhiteSpace(nameBox.Text) 
        && !String.IsNullOrWhiteSpace(authorBox.Text))
    {
